-- GENERATED by `wfj generate` from data/quest/quest-0098.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [98013] = { "Forze crescenti", "Elimina $N1 Stormscale Myrmidon, $N2 Stormscale Sorceress e $N3 Stormscale Warrior per Arbal al ⟦Grove of the Ancients=Bosco degli Antichi⟧.", "Preparati al tempo che passerai tra le rovine, giovane... lì non ti sarà concesso libero passaggio.\n\nSchiere di ⟦Highborne=Alti Nobili⟧ maledetti, oggi noti come naga, vagano per quella che un tempo era una grande città. Viaggia verso nord-est e cacciali da questa terra.\n\nCiò che erano un tempo... non esiste più. Se aiutano il ⟦Twilight's Hammer=Martello del Crepuscolo⟧, non possono che portare altro dolore alle foreste che un tempo diedero loro riparo.\n\nÈ la guerra che cercano, {class}. E la guerra... è ciò che porteremo.", nil, nil, 0xae8b4fd3, 0x2a0b423f, 0x83d7b2a0, nil, nil, "...mm" },
  [98021] = { "Viaggio a ⟦Sentinel Hill=Guardiacolle⟧", "Fai rapporto a Gryan Stoutmantle a ⟦Sentinel Hill=Guardiacolle⟧, nelle ⟦Westfall=Marche Occidentali⟧.", "Se vuoi cominciare a fare del bene nel nostro mondo, ti consiglio di presentarti a un uomo di nome Gryan Stoutmantle, nelle ⟦Westfall=Marche Occidentali⟧ a sud, presso l'insediamento noto come ⟦Sentinel Hill=Guardiacolle⟧. La sua gente ha bisogno di aiuto.\n\nDopo aver viaggiato fin qui da un altro piano dell'esistenza, i problemi delle nostre terre potranno sembrarti piccoli. Ti assicuro che l'aiuto che porti a chi ne è colpito significa tutto per loro, e le tue fatiche ti renderanno più forte.\n\nBuona fortuna là fuori, <avventuriero/avventuriera>!", nil, "Sono mesi che imploro aiuto a ⟦Stormwind=Roccavento⟧, e mi mandano <un/una> <elfo/elfa> <mingherlino/mingherlina>? Be', chi ha bisogno non può fare lo schizzinoso, suppongo.\n\n<Benvenuto/Benvenuta> nelle ⟦Westfall=Marche Occidentali⟧, {class}. Vediamo se riusciamo a metterti al lavoro.", 0xc1c4216f, 0x617304a7, 0x0210f242, nil, 0x0fdf4331, "...m." },
  [98024] = { "Viaggio al ⟦Crossroads=Crocevia⟧", "Presentati a Thork al ⟦The Crossroads=Crocevia⟧, nelle ⟦The Barrens=Savane⟧.", "Dopo il viaggio fin qui dal piano elementale, i problemi delle nostre terre potranno sembrarti piccoli. Ma stai pur cert<o/a> che i pericoli che l'Orda affronta sono più che reali, e diventerai formidabile se sopravvivrai al tuo servizio.\n\nSe vuoi cominciare a fare un po' di bene nel nostro mondo, viaggia a sud-ovest verso le vaste terre chiamate ⟦Barrens=Savane⟧. Lì c'è un insediamento noto come il ⟦Crossroads=Crocevia⟧. I suoi fieri abitanti hanno sempre bisogno di aiuto.\n\nVa' con onore, <avventuriero/avventuriera>!", nil, "Che cos'è questo? Un elfo? E dici che ti ha mandato il Capoguerra?\n\n<Thork grugnisce bruscamente squadrandoti da capo a piedi.>\n\nMi sembri un po' mingherlin<o/a>, ma non importa. Qui fuori o prosperi e sopravvivi, o muori. Così vanno le cose in queste terre.", 0xeac1fba3, 0x0ce1d543, 0x7fd58f06, nil, 0xd7076b4c, "...m." },
  [98025] = { "RICERCATA: Jai'vhanel", "Trova e uccidi la civetta nota come Jai'vhanel e prendi una delle sue piume. La civetta nera è stata vista l'ultima volta a nord delle rovine di ⟦Ameth'Aran=Ameth'aran⟧, ai piedi della montagna. Riferisci la morte di Jai'vhanel alla sentinella Glynda Nal'Shea ad Auberdine.", "Attenzione!\n\nÈ offerta una ricompensa per la morte della civetta \"Jai'vhanel\", nota anche come \"Swordfeather\".\n\nPurtroppo questa civetta è impazzita e ha cominciato ad attaccare i viaggiatori lungo la strada vicino ad Auberdine.\n\nJai'vhanel è stata vista l'ultima volta a nord delle rovine di ⟦Ameth'Aran=Ameth'aran⟧, ai piedi della montagna. Riporta una delle sue piume nere come il giaietto come prova della sua morte.\n\nLa ricompensa per questa taglia va riscossa presso la sentinella Glynda Nal'Shea ad Auberdine.\n\nIl Consiglio del villaggio di Auberdine", "Salute, {class}. In cosa possono aiutarti le ⟦Sentinels=Sentinelle⟧ oggi? Forse sei qui per chiedere della taglia su Jai'vhanel?", "È bene sapere che la questione è stata risolta, ma mi rattrista che non abbiamo trovato un'altra strada. Jai'vhanel era da molto tempo una sorta di guardiana di questa zona, e non so cosa possa averla spinta nella follia.\n\nIn ogni caso, grazie per il tuo servizio di oggi, {class}. Le strade per Auberdine sono di nuovo sicure.", 0x85ab0f27, 0x9af9befe, 0x3578bfb5, 0x84f21aff, 0xc148bf34, "....." },
  [98027] = { nil, "Consegna la collana con la falce di luna a Maliynn ad Astranaar.", "<La collana d'argento che hai tra le mani luccica dolcemente mentre la esamini. La piccola falce di luna somiglia ad altri simboli degli elfi della notte che hai già visto.\n\nGirando la collana trovi una piccola iscrizione: \"Alor'lormah, Maliynn\". Forse appartiene a Maliynn, ad Astranaar?>", nil, nil, 0xb3215af6, 0x8ae5ee49, 0x28957527, nil, nil, "e..mm" },
  [98028] = { "Il barone Marinous", "Porta il Clouded Water Globe a Onu al ⟦Grove of the Ancients=Bosco degli Antichi⟧, a ⟦Darkshore=Rivafosca⟧.", "Tutto ciò che resta del potente elementale è un globo di quella che sembra acqua pura, intorbidita da una sostanza sconosciuta. I bordi della sfera sembrano limpidi finché non la giri, come se la nube ti impedisse attivamente di scrutarvi dentro.\n\nQualunque cosa sia successa all'elementale, e alle rovine che sorvegliava, è ancora attiva in qualche modo.\n\nSolo Onu, l'Ancient of Lore del ⟦Grove of the Ancients=Bosco degli Antichi⟧, molto più a sud, potrebbe saperne di più.", nil, nil, 0x9d32a10a, 0xd906839f, 0x53a26984, nil, nil, "...mm" },
  [98042] = { "È tutto un gioco finché...", "Ottieni un Peerless Eye da un Twilight Disciple o da un Twilight Thug al ⟦Master's Glaive=Gladio del Maestro⟧, a ⟦Darkshore=Rivafosca⟧, e trova qualcuno ad Auberdine disposto a prenderlo.", "<Mentre strappi l'unica pagina dal Twilight Tome, una voce minacciosa ti invade la mente, senza invito.>\n\nHanno fallito.\n\nSarai dimenticat<o/a>.\n\nPerderanno l'occhio che avevano ottenuto.", nil, nil, 0x780af214, 0x29e68b4e, 0x10cc5e5e, nil, nil, "...mm" },
  [98046] = { "La corona della terra", "Porta il Drained Vessel a Lariia nel ⟦Temple of the Moon=Tempio della Luna⟧, a Darnassus.", "<Lo sguardo dell'arcidruido Fandral Staghelm si fa sottile.>\n\nSei ancora qui?\n\nPrendi la fiala e sparisci dalla mia vista, {class}. È chiaro che le mie risposte non si trovano nelle acque, proprio come prima.\n\nForse una delle sacerdotesse nel ⟦Temple of the Moon=Tempio della Luna⟧, a sud, se ne sbarazzerà.\n\n<Fandral distoglie lo sguardo e smette di parlarti.>\n\nDevo cercare altrove, se voglio che funzioni...", "Come posso aiutarti?", "Non badare all'arcidruido, {name}. Porta sulle spalle un grande peso, in assenza di Malfurion.\n\nAspetta! Nella fiala sono rimaste ancora alcune gocce! Forse è per questo che il suo incantesimo è fallito?", 0x6a9c354f, 0xfa735665, 0x87e3b8dc, 0xa26e2aed, 0x8094bf8b, "....." },
  [98059] = { "Il tesoro di Colletorto", "Metti la Sealed Company Request che ti è stata consegnata sul tavolo della contabilità, nel municipio di Colletorto.", "Il consiglio di Colletorto non ha risposto alle lettere del nostro nuovo magistrato. Le ultime notizie che ho strappato a un mercante di passaggio venuto dal villaggio non bastano certo a giustificare il loro silenzio.\n\nChiediamo solo un piccolo plotone, eppure mi dicono che diverse baliste d'assedio riposano in condizioni perfette dentro un complesso cinto da mura.\n\nEntra nel loro municipio come un cittadino che riconsegna un modulo del censimento e posa questa, in bell'ordine, sul tavolo della contabilità.\n\nTorna da me a cosa fatta.", nil, nil, 0x741522bc, 0xd8226166, 0x3f1e8fb4, nil, nil, "...mm" },
  [98065] = { "La corona della terra", "Porta i Moonwell Remnants a Tyrande Whisperwind nel ⟦Temple of the Moon=Tempio della Luna⟧, a Darnassus.", "Devi portare subito questi resti a Tyrande! Li verserò per te in un contenitore più cerimoniale.\n\nNon avere paura. La somma sacerdotessa di Elune è severa, ma gentile. Protegge tutti coloro che entrano a Darnassus e porta a tutti la luce della nostra dea.\n\nSarà lieta di ricevere quest'acqua sacra. La troverai proprio sopra di noi.", "Di' pure cosa ti porta qui. Ho una città da governare e un popolo da guidare.", "Staghelm ha fatto molto in assenza del mio amato, ma non è Malfurion. E non è lui a reggere gli affari di Darnassus: quel fardello spetta soltanto a me.\n\n<Il volto di Tyrande si distende.>\n\nTi chiedo scusa. Come probabilmente hai visto, abbiamo molte sfide da superare.\n\nPer ora Fandral è l'arcidruido, e ti chiedo di rispettare il suo rango. Ma le sue faccende riguardano il druidismo, mentre le mie non riguardano solo Elune, ma anche guidare il nostro popolo secondo la sua volontà.\n\nOgni goccia di quest'acqua è benedetta dalla nostra dea. Ti ringrazio per averla salvata.", 0x6a9c354f, 0x283abfd9, 0x13bb30c2, 0x073bf605, 0xf8575459, "....." },
  [98067] = { "Gli occhi delle ⟦Sentinels=Sentinelle⟧", "Colloca i gufi sentinella all'ingresso delle profondità della ⟦Cenarion Hold=Fortezza Cenariana⟧, alla banca di Darnassus, alla locanda della Terrazza degli Artigiani e alla porta della città per la sentinella Dalia Sunblade nel ⟦Temple of the Moon=Tempio della Luna⟧, a Darnassus.", "La generale Feathermoon fa in modo che tutte le sentinelle abbiano il tempo di pregare Elune. Una vera cacciatrice non brandisce solo la lama, ma anche i doni della dea per sconfiggere i nostri nemici.\n\nPuoi aiutarmi nei miei compiti quotidiani. Colloca delle sentinelle in giro per la città: comincia dalle gallerie che scendono sotto la ⟦Cenarion Hold=Fortezza Cenariana⟧, a nord, poi la banca al centro della città, la locanda della Terrazza degli Artigiani a nord-est e le porte della città. Le guardie possono aiutarti.\n\nC'è qualcosa che non va a Teldrassil: dobbiamo restare vigili.", nil, "Ti ringrazio per il tuo aiuto. Anche se trovo pace nei riti quotidiani, è bello avere invece un momento per riflettere.", 0xf4253869, 0xe7a28828, 0x37765008, nil, 0x026be8bd, "...m." },
  [98069] = { nil, "Porta 8 Stolen Freewind Supplies a Jandia al ⟦Freewind Post=Presidio di Ventolibero⟧.", "Quelle maledette arpie! Hanno attaccato l'ultima carovana che avevo organizzato per portare rifornimenti al ⟦Freewind Post=Presidio di Ventolibero⟧. Per il momento ne abbiamo abbastanza, ma senza altri rifornimenti presto resteremo a corto.\n\nNon so cosa vogliano farsene le arpie dei rifornimenti in più, ma ti sarei riconoscente se li recuperassi per me. Hanno la tana a ovest di qui. Le trovi sia ai piedi della scogliera sia dentro una grotta in cima.", nil, nil, 0x02f16acd, 0xcd999837, 0x21c7f07a, nil, nil, "e..mm" },
  [98070] = { "Basta strilli", "Uccidi $N1 Screeching Harpy, $N2 Screeching Roguefeather Harpy e $N3 Screeching Windcaller Harpy.", "Il ⟦The Screeching Canyon=Canyon Stridente⟧ ospita una banda di arpie del posto, nota per la sua ferocia e le sue tattiche di razzia. Hanno teso un'imboscata alle ultime carovane di rifornimenti che hanno avuto il coraggio di attraversare questo luogo.\n\nTemo che, se non si fa qualcosa presto, nessuna carovana oserà più affrontare il viaggio fino al ⟦Freewind Post=Presidio di Ventolibero⟧.\n\nVa', uccidi quante più arpie puoi. Torna da me a cosa fatta e ti ricompenserò bene per i tuoi sforzi.", nil, nil, 0x6fb557e1, 0x9dc5d06f, 0x8ecd48af, nil, nil, "...mm" },
  [98071] = { "Scambi tra birrai", "Consegna le bottiglie di Fallrook Varietal a Dun Garok, nel sud-est delle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, e riporta un sacco del loro Homebrew Hops.", "Ho fatto un piccolo scambio coi birrai di Dun Garok. A quanto pare non siamo gli unici a rimpiangere i vigneti della famiglia Fallrook! Le annate migliori in bottiglia sono state bevute da un pezzo, ma in cantina abbiamo ancora qualche cassa di quel vino.\n\nPorta questa cassa di Fallrook Varietal a Dun Garok, a sud-est, e lasciala a loro vicino al focolare dove si riuniscono, in fondo al forte.\n\nIn cambio, riportati indietro un sacco di Homebrew Hops.\n\nQuella fortezza è la cosa più simile a casa da queste parti!", nil, nil, 0xdbd8fe1c, 0xad567a8c, 0xe5403776, nil, nil, "...mm" },
  [98072] = { "Coccodrilli del cielo", "Raccogli 8 Pristine Crimson Scale e portale a James Halloran a ⟦Menethil Harbor=Porto di Menethil⟧.", "Ti dai proprio da fare! Ho solo un ultimo favore da chiederti, se te la senti di fare qualcosa di un po' più pericoloso.\n\nIl commercio di crocolischi rende bene e con costanza, ma è roba da poco rispetto a quanto fruttano le scaglie di cucciolo di drago. La gente paga fior di quattrini per un sacco di quelle.\n\nCoccodrilli del cielo, li chiamo io! Il mio apprendista non riuscirebbe mai a procurarsele, ma per te sembra proprio pane per i tuoi denti!\n\nTroverai i cuccioli di drago molto più a est, lungo la Green Belt. Ma sta' attent<o/a>, su quelle colline ci sono orchi feroci!", nil, nil, 0x3db2cf68, 0xba342fd8, 0x793428d8, nil, nil, "...mm" },
  [98093] = { "Un campo da sgombrare", "Sulhasa, nelle ⟦Barrens=Savane⟧ meridionali, vuole che tu elimini $N1 Stormhide e $N2 Hecklefang Stalker nella zona, così da poter scendere dall'albero in sicurezza.", "Sono così felice che tu mi abbia vista!\n\nStamattina il tempo era splendido, così sono scesa a piedi da Camp Taurajo lungo la strada dorata. Quando è stato il momento di tornare non ci sono riuscita: un branco di iene ha cominciato a girarmi intorno e le lucertole Stormhide mi hanno bloccato l'unica via di fuga.\n\nCosì mi sono arrampicata su quest'albero, e ora, a quest'ora, ci sono troppi nemici in giro perché io possa correre a casa attraverso i campi.\n\nTi dispiacerebbe eliminare questi Stormhide e Hecklefang Stalker per me?", nil, nil, 0x08f3d4db, 0x04fff6f2, 0x872fbe59, nil, nil, "...mm" },
  [98094] = { "Sostegno all'esploratore", "L'alta esecutrice Darthalia vuole che tu consegni gli ordini aggiornati all'⟦Deathstalker=Inseguitore della Morte⟧ Masoj, a sud del ⟦Tarren Mill=Mulino di Tarren⟧, fuori da Dun Garok.", "Ora che possiamo fidarci di te per consegnare informazioni vitali alle nostre spie avanzate, c'è un compito in più per te.\n\nPorta questo all'⟦Deathstalker=Inseguitore della Morte⟧ Masoj, quasi esattamente a sud di qui. Avrà altro da farti fare quando sarai lì e glielo avrai consegnato. È appostato su un'altura a nord della vigna marcia che chiamano ⟦Nethander Stead=Cascina dei Nethander⟧.\n\nIl nostro piano per prendere il controllo di queste terre procede senza sosta.", nil, nil, 0x7440188e, 0x30f9063e, 0xb2d0b01d, nil, nil, "...mm" },
  [98095] = { "Punti d'osservazione preziosi", "L'⟦Deathstalker=Inseguitore della Morte⟧ Masoj ha bisogno che tu collochi le tre Apothecary Vials su alcune vette delle ⟦Hillsbrad Foothills=Alture di Colletorto⟧ e torni da lui.", "Il nostro alto comando inserisce truppe strategiche con i cavalcatori di pipistrelli. I punti chiave intorno alle alture hanno perso i loro segnali di richiamo.\n\nPrendi queste fiale. Stappale in tre punti: le colline al confine con Dun Garok, l'altopiano che domina il Forte Durnholde e infine la cresta di Altocolle, sopra il villaggio di ⟦Hillsbrad=Colletorto⟧. I vapori che ne usciranno saranno come un potente diapason per i sensi dei pipistrelli, e li attireranno di nuovo ai punti di sbarco stabiliti.\n\nCerca le fiale vuote schiacciate e rinnova i nostri segnali.", nil, nil, 0x9e9c3c95, 0xa522d3ad, 0xde0f6623, nil, nil, "...mm" },
  [98155] = { "Pelli intatte di Pesterhide", "Porta $N1 Pristine Pesterhide Pelt a Kristy Grant.", "Le iene Pesterhide di ⟦Thousand Needles=Millepicchi⟧ hanno i manti più splendidi. In tutti i miei viaggi non ho mai visto una pelliccia di una tinta così brillante!\n\nVorrei mandare qualche pelle alle mie sorelle a ⟦Stormwind=Roccavento⟧, perché so che potrebbero ricavarne qualcosa di incredibile.\n\nNon ho alcuna esperienza di combattimento, quindi ti sarei davvero riconoscente se potessi raccogliere qualche pelle di Pesterhide al posto mio.", nil, nil, 0x5f2a26ec, 0x5d7bef18, 0x023d45ab, nil, nil, "...mm" },
  [98156] = { "Pelli intatte impacchettate", "Porta il Package of Pristine Pelts a Kimberly Grant.", "{name}, mi sei <stato/stata> così d'aiuto che mi dispiace chiederti un altro favore. Ci vorrà un po' prima che io possa tornare a casa, a ⟦Stormwind=Roccavento⟧. Mi chiedevo se ti andrebbe di consegnare queste pelli alle mie sorelle al posto mio.\n\nDi sicuro tornerai lì prima di me. Ti prego, consegna queste pelli alle mie sorelle Kelly e Kimberly a ⟦Stormwind=Roccavento⟧. Di solito si trovano nel Parco.", nil, nil, 0x702cae31, 0x518a3bbe, 0x39319c08, nil, nil, "...mm" },
  [98189] = { "La restituzione della statuetta", "Porta la ⟦Menethil Statuette=Statuetta di Menethil⟧ al capitano Stoutfist al ⟦Menethil Keep=Forte di Menethil⟧.", "Santo cielo, è... è bellissima!\n\nLa Blind Princess doveva consegnarla a ⟦Menethil Harbor=Porto di Menethil⟧ prima che accadesse la tragedia. Eravamo così vicini!\n\nCredo che a firmare la ricevuta dovesse essere il capitano Stoutfist, al ⟦Menethil Keep=Forte di Menethil⟧, proprio alle nostre spalle. Perché non hai tu l'onore di portare a termine il lavoro?", nil, nil, 0x6359787c, 0x0c8c34af, 0x67af9a56, nil, nil, "...mm" },
  [98190] = { "Un amico di famiglia", "Porta la ⟦Menethil Statuette=Statuetta di Menethil⟧ al gran signore Bolvar Fordragon nel Castello di ⟦Stormwind=Roccavento⟧.", "Dovrai portarla subito a ⟦Stormwind=Roccavento⟧. Per quanto sia orgoglioso che questa fortezza e questo porto portino il nome di re Terenas Menethil II, siamo un porto tranquillo in mezzo a una bruttissima tempesta di nemici. Qui non è sicuro.\n\nLe Fauci di Drago, in particolare, sacrificherebbero molto per mettere le mani su una cosa del genere... e rabbrividisco al pensiero di cosa ne farebbero.\n\nStavolta non perdere tempo a risalire la catena di comando, <ragazzo/ragazza>. Portala direttamente al gran signore Fordragon. Lui saprà dove custodirla al meglio.", nil, nil, 0xd13a5ecd, 0xb560772b, 0xcc6c0655, nil, nil, "...mm", nil, nil, 0x8176cdb8, nil, nil },
  [98191] = { "Un amico di famiglia", "Porta la ⟦Menethil Statuette=Statuetta di Menethil⟧ a lord Grayson Shadowbreaker nella ⟦Cathedral of Light=Cattedrale della Luce⟧.", "Re Terenas era un brav'uomo. Un uomo devoto. Amato dal suo popolo, e davvero la ragione per cui esiste questa ⟦Alliance=Alleanza⟧.\n\nL'ironia è che era umile: detestava questo genere di monumenti commemorativi, e così ne esistono pochissimi. E di quei pochi, pochi sono sopravvissuti alla caduta di Lordaeron.\n\nSembra che la Luce si sia condensata in questa statuetta. Sarebbe meglio custodirla nella Cattedrale della Luce, in Cathedral Square, al centro della città. Portala a lord Grayson Shadowbreaker perché la custodisca.", nil, nil, 0xd13a5ecd, 0x89dd523c, 0x35ad547b, nil, nil, "...mm" },
  [98197] = { "Bottino di guerra", "Recupera $N1 Khaz Modan Timber e $N2 Khaz Modan Iron a ⟦Menethil Harbor=Porto di Menethil⟧ per Valstag Ironjaw.", "Questo porto fu costruito in origine dalla vecchia ⟦Horde=Orda⟧ come base per l'invasione navale di ⟦Hillsbrad=Colletorto⟧. Aggirò del tutto le difese di Lordaeron!\n\nQuante vite perdute...\n\nE il peggio è che quella flotta fu costruita proprio con le risorse rubate a Khaz Modan!\n\nNe è rimasta parecchia nel porto, dopo che l'ammiraglio Proudmoore mise in rotta quei bruti e costruì questo posto per l'⟦Alliance=Alleanza⟧. Ci servirà per rafforzare le difese della città, ora che le Fauci di Drago si stanno muovendo.", nil, nil, 0x39128c53, 0xed2e4170, 0xa2e5a960, nil, nil, "...mm" },
  [98208] = { "Il Fiore dei Cieli", "Recupera Nord'el per Sylessa Duskwhisper a ⟦Menethil Harbor=Porto di Menethil⟧.", "Ho viaggiato da Auberdine, dal grande albero Teldrassil, fino a ⟦Menethil Harbor=Porto di Menethil⟧ per recuperare un fiore di grande importanza per il mio popolo.\n\nLa nave del mio popolo, la Flying Osprey, è naufragata qui molte lune fa, insieme alla Terza Flotta Kul Tirana. Nel suo carico c'era il fiore noto come Nord'el, Fiore dei Cieli nella tua lingua, sbocciato sotto la luna piena sulla vetta del ⟦Mount Hyjal=Monte Hyjal⟧, la nostra antica dimora.\n\nTi prego, aiutami a recuperarlo! Il relitto è appena a sud della città, ma è infestato da feroci predoni murloc!", nil, nil, 0x67289a3e, 0x145af630, 0xc0d3a012, nil, nil, "...mm" },
  [98209] = { "Il Fiore dei Cieli", "Porta Nord'el a Thundris Windweaver ad Auberdine, a ⟦Darkshore=Rivafosca⟧.\n\nRicordi che Sylessa ha parlato di una nave a ⟦Menethil Harbor=Porto di Menethil⟧ che può portarti lì.", "Potresti consegnare Nord'el all'anziano Thundris Windweaver ad Auberdine?\n\nLa nave da qui dovrebbe portarti lì in fretta.\n\nMi scuso per la richiesta, davvero. Il viaggio fin qui mi ha tolto ogni forza, e così la fuga da quei diavoli di murloc quando ho tentato per la prima volta di recuperare il fiore sacro!", nil, nil, 0x67289a3e, 0x740a8c63, 0xa8fde18c, nil, nil, "...mm" },
  [98216] = { "Comprendere il nostro presente", "Usa la Goaz Stone vicino al Goaz Warder e riporta la sua Titanic Keystone al prospettore Whelgar.", "Dei Antichi?! Questa non può essere affatto una buona notizia!\n\nHo decifrato un nuovo pezzo della pietra che parla di un guardiano di qualche tipo. Qualunque cosa sia, dev'essere legato alla pietra!\n\nPortala con te e vedi se riesci a trovare un grosso costrutto dei Titani da qualche parte negli scavi. Leggi quest'ultimo passaggio sulla pietra e guarda cosa succede!\n\nSe ho ragione, attiverai quell'affare. In tal caso fallo fuori, ma cerca di preservare tutto ciò che è interessante! Dobbiamo assolutamente saperne di più!", nil, nil, 0x58a10f76, 0xbfb2440c, 0xd453c4da, nil, nil, "...mm" },
  [98219] = { "Il tenente in disgrazia", "Parla con il tenente Farren Orinelle a ⟦Southshore=Riva del Sud⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧.", "Grazie ancora per aver consegnato la statuetta sana e salva, {name}.\n\nMi serve il tuo aiuto per un'altra faccenda. C'è un membro della guardia cittadina che è stato riassegnato a ⟦Southshore=Riva del Sud⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧.\n\nSuo padre era un mio amico, e anche se non nego che la lezione gli farebbe bene... vorrei comunque vederlo riuscire. Gli sarebbe davvero utile avere qualcuno come te ad aiutarlo.\n\nC'è una nave che può portarti da quelle parti da ⟦Menethil Harbor=Porto di Menethil⟧, se ci ripassi.", nil, nil, 0xc567588f, 0x4c7ba953, 0xc1f837e2, nil, nil, "...mm" },
  [98221] = { "Dalle ceneri", "Il capitano Stoutfist al ⟦Menethil Keep=Forte di Menethil⟧ vuole che tu distrugga i 4 piani d'attacco nell'⟦Angerfang Encampment=Accampamento Zannarabbiosa⟧.", "Durante la Seconda Guerra le Fauci di Drago costruirono una flotta proprio qui dove ci troviamo, con l'intento di prendere ⟦Hillsbrad=Colletorto⟧. Ci riuscirono quasi!\n\nFurono messi in rotta dai draghi rossi, e ne rimasero solo pochi sbandati nel profondo delle montagne. Eppure c'è stato un forte aumento di attività nel loro accampamento a nord-est di Menethil.\n\nDun Algaz è la prova che intendono marciare di nuovo in guerra e riprendersi questa terra. Trova i loro piani d'attacco, prendi nota di ogni informazione cruciale e distruggili. Dobbiamo sapere dove colpiranno la prossima volta!", nil, nil, 0x08a75e96, 0x18b3d712, 0xa9a35620, nil, nil, "...mm" },
  [98223] = { "Vecchie abitudini", "Porta il Tattered Spellbook al capitano Stoutfist a ⟦Menethil Harbor=Porto di Menethil⟧.", "Questo libro è gravemente bruciato, forse dal fuoco di drago che annientò gran parte del clan delle Fauci di Drago.\n\nDal poco che è leggibile, sembra descrivere rituali legati all'uso della Demon Soul, che il clan aveva usato per controllare i draghi.\n\nÈ troppo incompleto per essere davvero utile, ma da alcune pagine di pelle animale inserite alla buona sembra che Nek'rosh abbia tentato di recuperarlo. Un inchiostro asciugato di recente parla di un \"⟦Shadow Council=Concilio dell'Ombra⟧\".\n\nIl capitano Stoutfist a ⟦Menethil Harbor=Porto di Menethil⟧ vorrebbe saperlo.", nil, nil, 0x75c9f241, 0x3bf963b0, 0xe438fb44, nil, nil, "...mm" },
  [98230] = { "Questa terra era la loro terra", "Trova Howin Kindfeather a est di ⟦Menethil Harbor=Porto di Menethil⟧, lungo la strada.", "Dopo la Guerra dei Tre Martelli, che fece a pezzi la vita dei nani come la conoscevamo, i Granmartello si stabilirono qui e fondarono la fortezza di montagna di Grim Batol.\n\nEra un luogo meraviglioso. Ovunque guardassi c'erano grifoni in volo, che scendevano in picchiata sulle paludi per afferrare un pesce.\n\nPurtroppo non durò a lungo.\n\nHowin Kindfeather è uno dei primi Granmartello a tornare da secoli. Se ne sta per conto suo, ben lontano dalla città. Segui la strada verso est: prima o poi lo troverai. Di certo gli farebbe comodo una mano.", nil, nil, 0x5ef5a781, 0x920b4ded, 0xb7089ef8, nil, nil, "...mm" },
  [98240] = { "Consegna della Crimson Crate", "Porta la Crimson Crate a Howin Kindfeather, appena fuori dalla strada a est di ⟦Menethil Harbor=Porto di Menethil⟧.", "La voce su quelle scaglie di cucciolo di drago si è ufficialmente sparsa, {name}. Abbiamo già un ordine!\n\nTe le impacchetto per bene, poi tu le porti al cliente. Lo so, lo so: è solo un ultimo favore, lo prometto!\n\nSono per un certo \"Howin Kindfeather\". Ha mandato in città il suo grifone, figurati, con una lettera per l'ordine! Dice che si trova appena fuori dalla strada a est, un po' oltre gli ⟦Whelgar's Excavation Site=Scavi di Whelgar⟧, se li conosci.", nil, nil, 0xed839e17, 0xdfb38dba, 0x708169ee, nil, nil, "...mm" },
  [98245] = { "Denti di Razormaw", "Raccogli $N1 Razormaw Incisor per Howin Kindfeather.", "Non so chi odio di più: quei maledetti Ferroscuro, le Fauci di Drago o i draghi che cavalcavano.\n\n<Howin sputa.>\n\nIntendo rimettere le cose a posto. Ma ci serviranno delle provviste.\n\nQueste scaglie di cucciolo di drago proteggono parecchio dal fuoco di drago, ma intrecciarle è una vera rogna.\n\nI raptor Razormaw su alla ⟦Raptor Ridge=Dorsale dei Raptor⟧ a nord-est e alla ⟦Saltspray Glen=Radura Salmastra⟧ a nord-ovest devono il nome alle loro zanne aguzze: dovrebbero riuscire a forare le scaglie.\n\nPortami una manciata di incisivi.", nil, nil, 0x3df51a68, 0x27f4ab42, 0xb03dc652, nil, nil, "...mm" },
  [98246] = { "Tempi duri", "Raccogli $N1 Perfect Razormaw Egg per Howin Kindfeather.", "Mi servono delle uova se voglio che il mio piano funzioni. Bassbeak ha bisogno di una bella pancia piena: non ho nessuna intenzione di saltare in groppa a un grifone scorbutico.\n\nDevono essere perfette: niente crepe o roba del genere.\n\nPrendile dai raptor Razormaw: sono noti per avere tuorli grandi quanto la zucca di uno gnomo. Li trovi alla ⟦Raptor Ridge=Dorsale dei Raptor⟧ a nord-est e alla ⟦Saltspray Glen=Radura Salmastra⟧ a nord-ovest.\n\nFacciamo una bella dozzina tonda, giusto per sicurezza.", nil, nil, 0x488226eb, 0x110e549b, 0x48bf38c6, nil, nil, "...mm" },
  [98247] = { "Etichetta di spedizione", "Consegna la Shipping Label a qualcuno all'emporio dell'Azeroth Commerce Authority, nelle ⟦Redridge Mountains=Montagne Crestarossa⟧.", "<Sul fianco della cassa, ora piena, c'è un'etichetta di spedizione strappata. Il nome del destinatario è andato perso, ma i dettagli sulla provenienza sono ancora leggibili.\n\n\"Proprietà dell'Azeroth Commerce Authority. Si prega di restituire le casse vuote o le spedizioni non consegnate al nostro emporio locale all'incrocio di ⟦Three Corners=Tre Cammini⟧, nelle ⟦Redridge Mountains=Montagne Crestarossa⟧. I corrieri saranno ricompensati per il tempo e il viaggio.\"\n\nAccanto al testo c'è una mappa disegnata alla buona della zona attorno alla destinazione indicata.>", "Ah, salute! Come posso esserti utile?", "Sei arrivat<o/a> nel posto giusto! Sono felice di registrarti tra i nostri affiliati. Nessun contratto da firmare e nessun impegno a pesarti sulle spalle. Ti chiediamo soltanto di aiutarci con diligenza a completare o a restituire le nostre consegne che trovi durante i tuoi viaggi.\n\nIn cambio sarai ricompensat<o/a> con del Merchant's Favor, con cui potrai acquistare i beni e i servizi che offriamo qui. Anzi, eccotene un po' per cominciare.\n\nE ora, per caso hai la cassa da cui viene questa?", 0xe6d6b8f1, 0x2c55cb98, 0x6fa4ac5c, 0xafcd45d6, 0xa89e1ba0, "....." },
  [98248] = { "Etichetta di spedizione", "Consegna la Shipping Label a qualcuno all'emporio della Durotar Supply and Logistics, vicino al ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧.", "<Sul fianco della cassa, ora piena, c'è un'etichetta di spedizione strappata. Il nome del destinatario è andato perso, ma i dettagli sulla provenienza sono ancora leggibili.\n\n\"Restituite le spedizioni danneggiate o le casse vuote all'emporio della Durotar Supply and Logistics, ora comodamente situato proprio a ovest del ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧. Il vostro tempo è prezioso e vi ricompenseremo per il disturbo!\"\n\nAccanto al testo c'è una mappa disegnata alla buona della zona attorno alla destinazione indicata.>", "Buongiorno, viaggiatore. Come posso aiutarti?", "Hai trovato il posto giusto, e stai parlando con la persona giusta! Posso segnarti come <uno/una> dei nostri nuovi soci. Nessuna scartoffia da parte tua: non ho voglia di averne altre tra i piedi.\n\nTi chiediamo solo di aiutarci a gestire le consegne compromesse che trovi durante i tuoi viaggi. Così guadagnerai del Merchant's Favor, che potrai usare per acquistare beni e servizi proprio qui. Eccotene un po' per sistemarti!\n\nPer caso hai la cassa a cui era attaccata questa etichetta?", 0xe6d6b8f1, 0x6b4c68ba, 0xdcdf21c0, 0xb87d2b33, 0x40fefe07, "....." },
  [98251] = { "Senza ritorno", "Uccidi $N1 Shadowhorn Stag e $N2 Ashenvale Bear, poi torna da Va'xug Firefure, a nord-ovest del ⟦Fallen Sky Lake=Lago Cielinfranto⟧.", "Graaah!\n\nSono furioso. Dicevano che ⟦Ashenvale=Valtetra⟧ era facile da attraversare. Facile per chi? Per le bestie? Per gli uccelli?\n\nUn attimo prima stavo raccogliendo un'erba, quello dopo ero intrappolato in questo burrone. Devo davvero fare il giro di mezza foresta per tornare dov'ero un momento fa?\n\nQuando sono così, i miei incantesimi diventano instabili e si comportano... in modo diverso.\n\nPotresti sfoltire un po' le bestie qui intorno? Persino i loro stupidi zoccoli mi danno sui nervi. Detesto questa foresta maledetta.", nil, nil, 0xda72cb7d, 0x793d1806, 0xd2c43c4c, nil, nil, "...mm" },
  [98252] = { "Un sentiero del Vuoto", "Guida l'⟦Eye of Kilrogg=Occhio di Kilrogg⟧ di Va'xug fino alla strada principale di ⟦Ashenvale=Valtetra⟧.", "Mostra al mio ⟦Eye of Kilrogg=Occhio di Kilrogg⟧ la via per uscire da questo burrone e tornare sulla strada di ⟦Ashenvale=Valtetra⟧. Tienilo in movimento: io lo seguirò appena vedrò un sentiero libero.\n\nIo resto qui: almeno uno di noi deve sapere dove si trova. Se perdi la strada, posso riportarti indietro attraverso l'occhio. Non ho intenzione di vagare alla cieca in due in questa foresta maligna.\n\nPosso mantenere il canale per quattro minuti. Non di più. Raggiungi la strada prima che la visione si spezzi, oppure torna da me e ci riproviamo.", nil, nil, 0x9e802cef, 0x41338fb7, 0xbaa5cde3, nil, nil, "...mm" },
  [98282] = { "Rischi alchemici", "Raccogli una Unruptured Stalker Gland al ⟦Thelgen Rock=Masso di Thelgen⟧ per Caitlin Grassman, a ⟦Menethil Harbor=Porto di Menethil⟧.", "Certe ricette alchemiche richiedono ingredienti che vengono da posti, beh, molto pericolosi. E spesso quelle sono solo le erbe di base! Gli altri ingredienti sono anche peggio!\n\nDevo preparare altro antiveleno prima di poter ripartire. Giuro, in questa palude è tutto velenoso. È come se il veleno scorresse nella terra stessa!\n\nMi puoi aiutare? Mi serve una ghiandola velenifera dei ragni del ⟦Thelgen Rock=Masso di Thelgen⟧, molto a sud-est. Ma dev'essere intatta, altrimenti ne uscirà troppo veleno prima che tu arrivi qui. Scusa!", nil, nil, 0x67b679f7, 0xac87cb29, 0xd937715e, nil, nil, "...mm" },
  [98283] = { nil, "Porta la Carnage's Head a Rethiel the Greenwarden, nella ⟦The Green Belt=Cintura Rigogliosa⟧.", "L'ordine naturale di questa terra si sta spezzando. Un tempo erano i raptor Razormaw a impedire che la vegetazione invadesse tutto. Ora vivono nel terrore del loro capobranco, che prende il nome dalla carneficina che si lascia dietro.\n\nTemo che la bestia sia stata fatta impazzire dal morbo che non siamo ancora riusciti a estirpare del tutto.\n\nRisponderà alla carne malata degli orsi infetti sotto la ⟦Raptor Ridge=Dorsale dei Raptor⟧, a nord-est. Lascia le loro viscere nella sua tana.\n\nCarnage arriverà. Portami la sua testa.", nil, nil, 0x77d7998b, 0x5b85ca0c, 0xf7724ed3, nil, nil, "e..mm" },
  [98284] = { "Campeggio 101: Incantamento", "Parla con Nasalanna Windsinger a Shen'dar Village per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Enchanted Lute per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0xb70a277c, 0xb4a29ffc, nil, nil, "...mm" },
  [98285] = { "Campeggio 101: Ingegneria", "Parla con lo Strange Hermit nella Shadowgale Forest per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Un ingegnere ha sempre mille risorse, e quando sei da solo nelle terre selvagge è sempre utile poter mettere a frutto il tuo mestiere. Nessun buon accampamento è completo senza qualche costrutto utile!\n\nSì, torna da me quando avrai fatto un po' di esperienza come ingegnere e ti mostrerò come costruire qualcosa di speciale!", nil, nil, 0x1cb4025b, 0x164e6328, 0xfb7e88ff, nil, nil, "...mm" },
  [98286] = { "Campeggio 101: Incantamento", "Parla con Nasalanna Windsinger a Shen'dar Village per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Enchanted Lute per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0xb70a277c, 0xb4a29ffc, nil, nil, "...mm" },
  [98287] = { "Campeggio 101: Ingegneria", "Parla con Sprite Jumpsprocket a ⟦Stormwind=Roccavento⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Reagent Bot per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xba6c8a24, 0x549b28c0, nil, nil, "...mm" },
  [98291] = { "Morte alle Fauci di Drago", "Uccidi $N1 Dragonmaw Reclaimer, $N2 Dragonmaw Soulbinder e $N3 Dragonmaw Infiltrator nel Dragonmaw Retreat per Howin Kindfeather.", "Ho intenzione di tornare a Grim Batol e riconquistarla per i Granmartello, {name}. O almeno d'imparare qualcosina.\n\nNon guardarmi così, eh. Lo so quali sono i rischi. Non ho mica intenzione d'entrare menando martellate a destra e a manca, sai.\n\nComunque, prima mi serve il tuo aiuto. Gli orchi delle Fauci di Drago sono in marcia proprio adesso. Sono dappertutto nel Dragonmaw Retreat, dove i draghi rossi li avevano sbaragliati la volta scorsa.\n\nDevi sfoltire le loro file prima che io abbia una qualche speranza d'avvicinarmi. Non puoi mancarli, se segui la strada verso est.", nil, nil, 0xa1aa470d, 0x3d74e20a, 0xda672ac7, nil, nil, "...mm" },
  [98293] = { "Disarmo forzato", "Raccogli $N1 Dragonmaw Armaments nel Dragonmaw Retreat, poi portali al capitano Stoutfist, al ⟦Menethil Keep=Forte di Menethil⟧.", "Le Fauci di Drago stanno ammassando armi d'ogni genere. Sarebbe saggio sottrargliele prima che possano armare altri soldati.\n\nAl capitano Stoutfist, al ⟦Menethil Keep=Forte di Menethil⟧, interesserebbero di sicuro.", nil, nil, 0xe87e8bcf, 0xa648dc25, 0x494ec9da, nil, nil, "...mm" },
  [98297] = { "Spezzare il ciclo", "Uccidi il Subdued Dragonspawn al ⟦Dragonmaw Gates=Portale delle Fauci di Drago⟧ per Howin Kindfeather.", "Ho fatto un breve volo di prova mentre eri via. La buona notizia è che l'armatura che mi hai aiutato a forgiare per Bassbeak funziona a meraviglia!\n\nLa pessima notizia è che ho visto un gruppo di quelle Fauci di Drago mentre riducevano in schiavitù una dragobestia rossa.\n\nNo, assolutamente no. Non un'altra volta.\n\nDevi farla fuori. E ti serviranno di sicuro degli amici per riuscirci. Prima uccidi gli stregoni che la tengono soggiogata: questo dovrebbe liberarla. Poi metti fine alle sue sofferenze.\n\nNessuno di loro si metterà sulla strada dei Granmartello.", nil, nil, 0xf76afbec, 0x67d75546, 0xf0dfba1f, nil, nil, "...mm" },
  [98298] = { "La follia di Arugal", "Porta $N1 Worgen Bits a Dalar Dawnweaver, alla ⟦The Sepulcher=Mausolea⟧.", "Ah, ora è tutto così imbarazzantemente chiaro! Arugal non aveva quasi nessuna magia, figuriamoci abbastanza da creare i worgen. La ⟦Arugal's Curse=Maledizione di Arugal⟧. Pah! Era a malapena abbastanza potente da durare qualche secondo.\n\nQueste catene dimostrano che sa vincolare le bestie, non crearle. È evidente che i worgen diffondono la maledizione in un altro modo. Voglio sapere come.\n\nVa' al Greymane Wall, a sud. Pare che i worgen si stiano diffondendo tra gli umani dei dintorni. Fai a pezzi le bestie e portami tutto ciò che trovi. Qui serve un approccio più diretto.", "Zanne, artigli, ventrigli. Per me non fa differenza. Il modo più semplice di studiare qualcosa è vederne le budella con i propri occhi.", "Pare che alla fine rida bene chi ride ultimo, ah ah! Arugal era davvero uno sciocco. E io, Dalar Dawnweaver, l'ho smascherato per l'impostore che è.\n\nQuesti pezzi sono tutte le prove che mi servono: la maledizione non ha niente a che fare con quell'idiota farneticante.\n\nPurtroppo, questo significa che anche il suo rimedio non vale niente. Pare che la ricerca di una soluzione alla maledizione dei worgen continui.", 0x93f7323d, 0x865fabf6, 0x0e0f701a, 0xc3554411, 0x385eae60, "....." },
  [98299] = { "Fermare il contagio", "Elimina $N1 Sickly Refugee e $N2 Haggard Refugee per Dalar Dawnweaver, alla ⟦The Sepulcher=Mausolea⟧.", "Se c'è una cosa che sappiamo, è che Arugal è responsabile dei worgen di ⟦Silverpine=Pinargento⟧, per opera delle sue macchinazioni o d'altro. Quello che non sappiamo è come si diffonda.\n\nMentre cerco un modo per fermare la maledizione, la nostra priorità è contenerla. Pare che questo male non possa contagiare i Reietti, ma un folto gruppo di umani si è radunato presso il Muro dei Mantogrigio.\n\nVa' al muro ed elimina quei profughi prima che abbiano la possibilità di diventare servitori di Arugal. E cerca di non farti mordere, {race}.", nil, "Pare che i Gilneani non siano molto propensi a lasciar passare qualcuno oltre il loro muro. Immagino sia una fortuna. Vuol dire che probabilmente la maledizione dei worgen non ha alcuna possibilità di diffondersi nella loro città.\n\nRiesci a immaginare la depravazione, se un intero regno fosse contagiato?", 0x030f1fc2, 0x16b6b162, 0xef81af04, nil, 0x800dc7c3, "...m." },
  [98300] = { "Notizie per ⟦Ironforge=Forgiardente⟧", "Consegna la Howin's Missive a re Magni Bronzebeard, a ⟦Ironforge=Forgiardente⟧.", "Il mio lavoro qui è tutt'altro che finito, {name}. E devo mandare notizie a mia moglie Claira, al ⟦Aerie Peak=Picco dell'Aquila⟧, e anche aggiornare Falstad.\n\nMa questi sono affari miei. Affari dei Granmartello.\n\nDetto questo, dovresti informare di tutto anche re Magni Bronzebeard, a ⟦Ironforge=Forgiardente⟧. Le ⟦Wetlands=Paludi Grigie⟧ sono a un tiro di sasso dalle sue terre, e niente di quello che sta succedendo qui è una bella notizia da trovarsi sulla soglia di casa. Questa lettera dovrebbe bastare.\n\nPer arrivare a ⟦Ironforge=Forgiardente⟧ puoi tornare indietro passando per Dun Algaz o volare da ⟦Menethil Harbor=Porto di Menethil⟧.", nil, nil, 0x70a6616f, 0x4ae70287, 0x38f01d76, nil, nil, "...mm" },
  [98310] = { "Raccogliere il nostro futuro", "Usa la Goaz Stone vicino ad Ados, Modr, Golm e Neru e riporta i loro cuori al prospettore Whelgar.", "Ci sono altri golem, più grandi, sparsi per le ⟦Wetlands=Paludi Grigie⟧. Ognuno porta un'iscrizione che lo identifica come Ados, Modr, Golm e Neru: proprio come i pezzi mancanti della Goaz Stone che hai trovato!\n\nScommetto che, se riusciamo a portare qui anche dei pezzi di quei golem, scopriremo un'altra parte della Goaz Stone!\n\nTroverai Ados al ⟦Dragonmaw Gates=Portale delle Fauci di Drago⟧, a est, vicino a Grim Batol. Modr è appena fuori da Dun Modr, a nord. Golm si trova sotto Grim Batol, a est di Dun Algaz. Neru è dietro il ⟦Direforge Hill=Colle Forgiatroce⟧, a nord-est.", nil, nil, 0x9ceacfd8, 0xe9da4d7c, 0x81be163b, nil, nil, "...mm" },
  [98313] = { "Per ulteriori studi", "Porta il Whelgar Relic Package allo storico Karnik, a ⟦Ironforge=Forgiardente⟧.", "Qualunque cosa ci sia sotto, {name}, è roba epica, poco ma sicuro.\n\nTi impacchetto tutto per bene. Portalo allo storico Karnik, nella Hall of Explorers di ⟦Ironforge=Forgiardente⟧. Di solito lo trovi in fondo, nella biblioteca, col naso affondato in qualche tomo.\n\nCi vorrà un esercito intero per risolvere questo mistero, ma se quello che abbiamo visto finora vuol dire qualcosa, ne varrà proprio la pena!", nil, nil, 0x89f4c96b, 0x0134cc07, 0x00b268a2, nil, nil, "...mm" },
  [98319] = { "Mettere al sicuro la montagna", "Trova il montanaro Cornelius nella Tana Selvaggia per conto della montanara Gretchen.", "È già abbastanza brutto avere un problema coi troll, ma le montagne sono piene zeppe di wendigo! Di solito se ne stanno nelle loro caverne, ma pare che si moltiplichino come conigli. Ora hanno invaso la Tana Selvaggia, qui a nord.\n\nSe vogliamo il rapporto per Whitebeard, dobbiamo trovare il mio compagno Cornelius. Quella testa di legno si è fatto prendere dall'entusiasmo e si è buttato dentro a testa bassa. Coraggioso, ma stupido.\n\nEntra nella caverna e scopri dov'è finito. E già che ci sei, fai pure fuori qualche bestia.", nil, "Ah, quello sciocco...\n\nGrazie per l'aiuto, {name}. Direi che abbiamo il nostro rapporto.", 0xe669cbf4, 0xd8ab5017, 0x14ff1bb4, nil, 0x46e44405, "...m." },
  [98321] = { "Il carico di Flintfire", "Raccogli $N1 Flintfire Shipment nella Tana Selvaggia per Tongus Flintfire, a Kharanos.", "Ohè! Fa piacere vedere <un/una> {race} che non ha paura di sporcarsi le mani.\n\nSe cerchi lavoro, temo di essere un po' a corto di materiali, al momento. La nostra fonte di minerale più affidabile è stata invasa dai wendigo e ora la caverna è abbandonata. I minatori hanno dovuto mollare tutto quando sono scappati!\n\nDi', perché non vai a dare un'occhiata alla Tana Selvaggia, a ovest, e vedi se trovi un po' dei nostri carichi perduti? Ci risparmieresti un sacco di grane.", "I wendigo sono bestiacce cattive. Meno male che tutti i minatori sono usciti sani e salvi dalla Tana Selvaggia!", "Così va meglio! Con questi carichi rimetteremo in funzione la forgia in un attimo!", 0xc0b8d385, 0xffee5126, 0xa4bbc762, 0x9fbc2026, 0x45d32722, "....." },
  [98322] = { "Mettere al sicuro la montagna", "Va' a vedere come sta la montanara Gretchen, a ovest di Kharanos.", "Esplorare caverne buie è affare da avventurieri. Il mio lavoro è solo stilare rapporti e mandarli a ⟦Ironforge=Forgiardente⟧.\n\nIl guaio è che uno dei miei rapporti non mi ha... beh, riportato niente. Ho chiesto ad alcuni montanari di saperne di più sul problema dei wendigo che abbiamo qui, ma non ho più avuto loro notizie.\n\nSe devi comunque andare in giro, che ne dici di passare a vedere come sta la montanara Gretchen, appena a ovest del paese? Sono già abbastanza in ritardo!", nil, "Ti manda il vecchio Whitebeard, eh?\n\nHo il suo rapporto, eccome. Tutta questa faccenda è un disastro!", 0xe669cbf4, 0x7154065a, 0xbebd5727, nil, 0xef2ba3dc, "...m." },
  [98323] = { "Mettere al sicuro la montagna", "Riporta il Mountaineer Gretchen's Report a Senir Whitebeard, a Kharanos.", "Spero che tu abbia fatto fuori un bel po' di quelle bestiacce mentre eri là dentro. Peccato per Cornelius, però.\n\nDa quello che mi hai raccontato, non c'è molto da riferire, a parte che la caverna è una causa persa. A Whitebeard la risposta non piacerà, ma non me la sento di mandare qualcun altro in quella trappola mortale.\n\nSentiti pure liber<o/a> di portargli il messaggio, {name}. Io non mi muovo da qui finché la montagna non sarà al sicuro.", "Ah, sei tornat<o/a> giusto in tempo.\n\nChe succede, ragazz<o/a>? Sembra che tu abbia visto un fantasma.", "Completamente invasa? Perché non mi sorprende?\n\nBeh, finirà anche questo nel rapporto.\n\n<Senir piega la lettera di Gretchen e la mette nella pila dei suoi appunti.>", 0xe669cbf4, 0x2405aa8a, 0xd096a625, 0x547dd283, 0x0cf43582, "....." },
  [98326] = { nil, "Elimina Frosthowl e recupera il Sack of Fish per Gretta Ganter, a ⟦Brewnall Village=Borgo Luppolo⟧.", "Lo sai quanto è difficile pescare su un lago ghiacciato? Il mio povero marito, Paxton, è là in mezzo da giorni e abbiamo a malapena un sacco di pesce da mostrare.\n\nBeh, un sacco da mostrare CE L'AVEVAMO. Finché quel dannatissimo wendigo non mi ha aggredita e si è portato via il nostro bottino. Ci vorranno settimane per ripescare tutto! Sempre che quel chiassone di Frosthowl non li abbia fatti scappare tutti, i pesci.\n\nFacci un favore e riprendilo, eh? Quel bruto sbavante si nasconde da qualche parte in fondo alla Tana Selvaggia, a sud-est.", "Farà caldo a Dun Morogh prima che io dica a Paxton di aver perso tutta la sua scorta per colpa di un wendigo.", "Mi hai salvato la vita, {name}!\n\nMio marito ci riderebbe sopra, ma non sopportavo l'idea di dirgli che doveva passare un'altra notte sul lago. Forse adesso potremo goderci un vero banchetto.", 0x08b6e05f, 0xea44c644, 0xbf80aad5, 0x9511dc93, 0x0c56d569, "e...." },
  [98338] = { nil, nil, nil, nil, nil, 0x33acc140, nil, nil, nil, nil, "emmmm" },
  [98340] = { "Il Grande Spirito Felino", "Parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "Sembra che tu sia <pronto/pronta> per il prossimo passo del tuo viaggio, giovane druido. Dendrite Starblaze ti ha mandato a chiamare e desidera che tu vada di nuovo a cercarlo a ⟦Moonglade=Radaluna⟧.\n\nHai già imparato a invocare la magia che ti porta a ⟦Moonglade=Radaluna⟧, quindi puoi partire subito, se vuoi. Ti suggerirei di andare presto, se desideri proseguire il tuo addestramento druidico.", nil, nil, 0xb22fd0a9, 0x127a78ca, 0xe8864144, nil, nil, "...mm" },
  [98341] = { "Il Grande Spirito Felino del Vento", "Cerca l'Avatar of Saeyleenan nella parte meridionale di ⟦Moonglade=Radaluna⟧ e scopri cosa ha da insegnarti sulla natura del felino del vento.", "Uno spirito della tua terra natale è apparso qui di recente e mi ha chiesto di guidarti da lui. Questo spirito felino del vento è venuto a istruirti e a farti da mentore, perché tu possa assumere la forma felina dello spirito di Zephras.\n\nPrima o poi tutti i druidi cercano questa saggezza, anche se pare che nella tua terra natale abbia una forma un po' diversa dalla nostra tradizionale. Se desideri assumere la forma felina di questo spirito, dovrai superare la nostra prova.\n\nLo troverai nella parte meridionale di ⟦Moonglade=Radaluna⟧, a sud dei ponti gemelli.", nil, nil, 0x802a0775, 0xa9c77684, 0xb2eb4e2f, nil, nil, "...mm" },
  [98342] = { "Il Grande Spirito Felino", "Recupera la Relic of the Fang, la Relic of the Claw e la Relic of the Silent Shadow negli Eremi di Grantempesta e riportale al Grande Spirito Felino.", "Per attingere al mio spirito non bastano poche parole. Per comprendere e rispettare la mia forma devi dimostrare di saper incarnare l'astuzia, la furtività e, se dovessi trovarti con le spalle al muro, la ferocia.\n\nNegli eremi appena a est di qui ci sono tre reliquie del mio favore, che devi recuperare. Sono sorvegliate da potenti spiriti infuriati che ti attaccheranno a vista. Una statua all'ingresso ti benedirà con una furtività temporanea per superarli.\n\nRiportami queste reliquie. Vedremo se sei <pronto/pronta> ad assumere la mia forma.", nil, nil, 0xb22fd0a9, 0x4c70cdf0, 0x6695208c, nil, nil, "...mm" },
  [98362] = { "Verso ⟦Thunder Bluff=Picco del Tuono⟧", "Torna a ⟦Thunder Bluff=Picco del Tuono⟧ e parla con Turak Runetotem sull'⟦Elder Rise=Altura degli Anziani⟧.", "È giunto il momento di separarci ancora una volta, giovane, perché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Sembra che il tuo istruttore, Turak Runetotem, abbia trovato in te un allievo degno. Credo di vederlo anch'io. Segui le sue lezioni e presto potrai attingere al Grande Spirito Felino per assumerne la forma.\n\nTorna da dove sei venut<o/a>. Quando sarà il momento, ci rivedremo.", nil, nil, 0xb1ea6f7d, 0x7484d02e, 0x94e47dad, nil, nil, "...mm" },
  [98372] = { "Una triste fine", nil, nil, nil, "Il corpo della sentinella dei Guardiani della Notte che giace davanti a te è coperto di squarci e tagli profondi. È evidente che l'uomo è stato sbranato da una grossa bestia.\n\nNoti che il cadavere stringe in mano una torcia spenta. Ti chini e la sfili dalle sue dita irrigidite. Potrebbe esserti utile nei tuoi viaggi per ⟦Duskwood=Boscovespro⟧ e oltre, per rivelare ciò che l'oscurità nasconde.", 0xc0c4b3d4, nil, nil, nil, 0x10acb436, ".mmm." },
  [98386] = { "⟦Alther's Mill=Segheria di Alther⟧", "Uccidi $N1 Greater Tarantula e distruggi $N2 Tarantula Egg alla ⟦Alther's Mill=Segheria di Alther⟧ per il caposquadra Oslow, a ⟦Redridge=Crestarossa⟧.", "Orchi, gnoll, murloc. Sembra che tutto voglia impedirmi di finire questo ponte in tempo. E ora ci arriva voce che la nostra segheria è infestata dalle tarantole!\n\nSe te la senti di guadagnare qualche moneta in più, potresti andare alla ⟦Alther's Mill=Segheria di Alther⟧, a est, e risolvere il loro problema con i ragni? Quel posto per me è praticamente inutile se non posso mandarci gli operai a ritirare i carichi in sicurezza.\n\nAh, e se vedi il vecchio Alther, digli che mi deve un favore per aver ripulito il suo pasticcio.", nil, "La segheria è messa così male? È peggio di quanto pensassi.\n\nNon sono particolarmente schizzinoso, ma il lavoro è già abbastanza duro senza ragni che mi portano via gli operai. Grazie dell'aiuto, {name}!", 0xe7ba8f99, 0x7745e897, 0xebb117bb, nil, 0x4d3ec210, "...m." },
  [98387] = { "Il blocco dei ⟦Blackrock=Roccianera⟧", "Porta $N1 Stolen Weapon e $N2 Blackrock Supplies al maresciallo Marris, a ⟦Lakeshire=Borgolago⟧.", "Non si combatte una guerra senza armi.\n\nGli orchi ⟦Blackrock=Roccianera⟧ si sono spinti fin dentro queste terre, ma la loro sfrontatezza non è priva di punti deboli.\n\nVa' a sud-est, sotto il ⟦Stonewatch Keep=Mastio di Guardamasso⟧, trova i loro accampamenti e prendi di mira le loro armi e le loro scorte.\n\nVedremo quanto sono pericolosi senza i loro strumenti di guerra.", "Quasi tutto quello che troverai sarà stato razziato a ⟦Lakeshire=Borgolago⟧, comunque. Mi farà bene sapere che la nostra gente prospererà mentre gli orchi appassiscono.", nil, 0xaf4ac457, 0x49a066b7, 0x2b169b79, 0x5ee2dc22, nil, "....m" },
  [98389] = { "Una luce nell'oscurità", "Libera $N1 Webbed Victim nella Valle Telanera per Aramis Hammerhand, ad ⟦Deathknell=Albamorta⟧.", "Salute, {class}. Sì, sono un paladino. Nemmeno la morte può fermare la Luce.\n\nÈ una cosa che quelli come me hanno in comune con tutti i Reietti: abbiamo superato ciò che i vivi considerano la propria fine. Eppure, alcuni persino tra i nostri ci temono; sospettano che li abbatteremo come mostruosità.\n\nIn verità, il nostro rapporto con la non morte è complesso, ma non sono qui per fare del male ai nostri. Aiutami a dimostrarlo agli altri. Va' alla Valle Telanera, a nord-ovest, e libera gli sciocchi appena risorti intrappolati dai ragni laggiù.", nil, "Che questo aiuti l'esecutore Arren e tanti altri a vedere la nostra vera natura. Proprio come nelle nostre vite passate, viviamo per servire il nostro popolo, per proteggerlo con i doni che la Luce ci concede.\n\nCol tempo capiranno che per i piani della Dama Oscura valiamo quanto chiunque altro.\n\nLa Luce sia con te.", 0x1a235ca8, 0xb759528e, 0xedcae565, nil, 0x388aed83, "...m." },
  [98391] = { "La Sisterhood of Elune", "Parla con la sorella Aquinne a Darnassus.", "Che tu sia benedett<o/a>, {class}. La Sisterhood of Elune è da migliaia di anni un pilastro della società kaldorei.\n\nPrima della Grande Separazione, prima della Guerra degli Antichi, durante la Lunga Veglia, abbiamo guidato e curato il nostro popolo attraverso l'oscurità. Questo è il nostro compito, e questo è ciò che chiede l'impareggiabile Madre Luna.\n\nOra abbiamo bisogno del tuo aiuto in una questione di grande importanza. La sorella Aquinne attende il tuo arrivo a Darnassus.", nil, "Sono lieta che tu sia arrivat<o/a> così in fretta. La Sisterhood ha bisogno del tuo aiuto.", 0xbbe6a9b4, 0x1f3d24f5, 0xd260a541, nil, 0x0410d1a8, "...m." },
  [98392] = { "Oscurità nella radura", "Recupera l'Hatescreech's Amulet, il Windmistress Gaedress' Amulet e il Witchmother Arysa's Amulet per la sentinella Arynia Cloudsbreak, nella Radura dell'Oracolo.", "Queste cinture... guarda bene il cuoio, {name}. Vedi la corruzione che scorre tra le fibre?\n\nHo un sospetto sulla sua origine, ma ci servono altre prove per esserne sicuri.\n\nTorna nei nidi delle arpie, a ovest, ed elimina i loro capi. Se le loro collane portano la stessa oscurità di queste cinture, avremo la nostra risposta.", "Hai strappato gli amuleti ai capi delle arpie?", "<Arynia esamina gli amuleti.>\n\nVedi i ripugnanti vortici verdi dentro le gemme? È proprio la corruzione del Vilmuschio all'opera.\n\nHo sentito notizie simili da ⟦Shadowglen=Vallombra⟧ e da altri punti tra i rami di questa sostanza che rivolge il nostro stesso mondo contro di noi.\n\nInformerò subito i miei superiori.", 0xaad1e9ab, 0xab3da6db, 0x662c4561, 0x5c33eda2, 0x1d4da464, "....." },
  [98393] = { "Il Grande Spirito Felino", "Parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "Sembra che tu sia <pronto/pronta> per il prossimo passo del tuo viaggio, giovane druido. Dendrite Starblaze ti ha mandato a chiamare e desidera che tu vada di nuovo a cercarlo a ⟦Moonglade=Radaluna⟧.\n\nHai già imparato a invocare la magia che ti porta a ⟦Moonglade=Radaluna⟧, quindi puoi partire subito, se vuoi. Ti suggerirei di andare presto, se desideri proseguire il tuo addestramento druidico.", nil, nil, 0xb22fd0a9, 0x127a78ca, 0xe8864144, nil, nil, "...mm" },
  [98394] = { "Il Grande Spirito Felino", "Cerca il Grande Spirito Felino nella parte meridionale di ⟦Moonglade=Radaluna⟧ e scopri cosa ha da insegnarti sulla natura del felino.", "Nella parte meridionale di ⟦Moonglade=Radaluna⟧, su una collina che domina il ponte, dimora un essere saggio e astuto che chiamiamo Grande Spirito Felino.\n\nProprio come il Great Bear Spirit, questo spirito è stato precettore e mentore dei druidi che desiderano assumere la forma felina. Prima o poi tutti i druidi cercano la sua saggezza, e se desideri assumere la forma di felino lo farai anche tu.\n\nVa' dal Grande Spirito Felino e impara ciò che vorrà insegnarti.", nil, nil, 0xb22fd0a9, 0x75cdb0e3, 0x65936190, nil, nil, "...mm" },
  [98396] = { "Il Grande Spirito Felino", "Recupera la Relic of the Fang, la Relic of the Claw e la Relic of the Silent Shadow negli Eremi di Grantempesta e riportale al Grande Spirito Felino.", "Per attingere al mio spirito non bastano poche parole. Per comprendere e rispettare la mia forma devi dimostrare di saper incarnare l'astuzia, la furtività e, se dovessi trovarti con le spalle al muro, la ferocia.\n\nNegli eremi appena a est di qui ci sono tre reliquie del mio favore, che devi recuperare. Sono sorvegliate da potenti spiriti infuriati che ti attaccheranno a vista. Una statua all'ingresso ti benedirà con una furtività temporanea per superarli.\n\nRiportami queste reliquie. Vedremo se sei <pronto/pronta> ad assumere la mia forma.", nil, nil, 0xb22fd0a9, 0x4c70cdf0, 0x6695208c, nil, nil, "...mm" },
  [98397] = { "Verso Darnassus", "Torna a Darnassus e parla con Mathrengyl Bearwalker nell'⟦Cenarion Enclave=Enclave Cenariana⟧.", "È giunto il momento di separarci ancora una volta, giovane, perché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Sembra che il tuo istruttore, Mathrengyl Bearwalker, abbia trovato in te un allievo degno. Credo di vederlo anch'io. Segui le sue lezioni e presto potrai attingere al Grande Spirito Felino per assumerne la forma.\n\nTorna da dove sei venut<o/a>. Quando sarà il momento, ci rivedremo.", nil, nil, 0xcf1122f7, 0x17d4d4c5, 0x86c4515f, nil, nil, "...mm" },
  [98398] = { "L'Albero dell'Oracolo", "Trova qui vicino l'Oracle Tree Bark per riceverne il messaggio.", "Sono colpita da ciò che sei riuscit<o/a> a fare qui in così poco tempo, {name}. Vorrei poterti chiedere di restare ad aiutarmi nei miei compiti... ma so in cuor mio che ti aspettano imprese più grandi.\n\nHo notato che l'Albero dell'Oracolo ha appena lasciato cadere un pezzo della sua corteccia. Di certo ha un compito che desidera veder portato a termine. Dovresti parlarci.", nil, "Mentre esamini la corteccia caduta, una voce ti entra nella mente. È calma e rassicurante, e ti avvolge come una brezza leggera tra le foglie.", 0x9c6398c9, 0xc836cbe1, 0x5c5a347c, nil, 0x36d45e10, "...m." },
  [98403] = { "Odio contorto", "Uccidi $N1 Befouled Webwood e porta il Mature Fel Moss di Xethorr il Malvagio a Tallonkai Swiftroot a Dolanaar.", "Lord Melenas non ha agito da solo: era al servizio di un altro. Colui che cerchi è Xethorr il Malvagio. Pare che abbia corrotto i ragni che vivono a Teldrassil, destinando il loro veleno a qualche piano immondo.\n\nSi è stabilito nel profondo della foresta, nella zona a nord-ovest di qui nota come the Cleft. Sii prudente e porta degli alleati, perché Xethorr non è un avversario da prendere alla leggera.\n\nElimina la sua covata e portami qualunque cosa possa dirci di più sulle attività del satiro qui.", "<Tallonkai abbassa la voce.>\n\nXethorr cammina ancora libero?", "Avrei dovuto sapere che questo veniva usato per corrompere i ragni di questa terra.\n\nHo sentito voci secondo cui questa sostanza sarebbe all'origine di gran parte della corruzione che ci affligge. Anche se questo non è l'originale, è un campione più vecchio e potrebbe fornire più informazioni di quante ne abbiamo ottenute finora.\n\nDi solito ti farei mandare questo a Darnassus per ulteriori studi. Tuttavia, per il momento è meglio tenere la cosa sotto silenzio, o Dolanaar non recupererà mai la sua reputazione.\n\nConfido che farai lo stesso.", 0x10738b8e, 0xa891e626, 0x8a01b9a3, 0x32ad7205, 0x7c0c6469, "....." },
  [98404] = { "Il Grande Spirito Felino del Vento", nil, nil, nil, nil, 0x802a0775, nil, nil, nil, nil, ".mmmm" },
  [98405] = { "Il Grande Spirito Felino", "Cerca il Grande Spirito Felino nella parte meridionale di ⟦Moonglade=Radaluna⟧ e scopri cosa ha da insegnarti sulla natura del felino.", "Nella parte meridionale di ⟦Moonglade=Radaluna⟧, su una collina che domina il ponte, dimora un essere saggio e astuto che chiamiamo Grande Spirito Felino.\n\nProprio come il Great Bear Spirit, questo spirito è stato precettore e mentore dei druidi che desiderano assumere la forma felina. Prima o poi tutti i druidi cercano la sua saggezza, e se desideri assumere la forma di felino lo farai anche tu.\n\nVa' dal Grande Spirito Felino e impara ciò che vorrà insegnarti.", nil, nil, 0xb22fd0a9, 0x75cdb0e3, 0x65936190, nil, nil, "...mm" },
  [98447] = { "La famiglia Valor", nil, nil, nil, nil, 0x27a57039, nil, nil, nil, nil, ".mmmm" },
  [98517] = { "Il richiamo del fuoco", "Presentati a Sessaria Skystride o ad Aarnor Galestrike sull'isola di Zephras per continuare il tuo addestramento come <Sciamano/Sciamana>.\n\nPuoi tornare a Zephras con il trasporto skycutter che attracca a Mulgore, allo Skywatcher Plateau, a nord-ovest di ⟦Thunder Bluff=Picco del Tuono⟧.", "Salute, giovane Skyborne. Gli spiriti mi hanno parlato di te e mi dicono che sei <pronto/pronta> a rispondere al richiamo del fuoco. Tuttavia, non sarò io a iniziarti su quel sentiero. Torna alla tua casa nel piano elementale e cerca lì i tuoi mentori. Ti diranno cosa deve essere fatto.", nil, nil, 0x53f3b76b, 0xe2cf2544, 0x04034459, nil, nil, "...mm" },
})
